import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`programmatic-seo`,heroTitle:`Generate your SEO pages in minutes`,heroSubtitle:`Perplexity Computer researches keywords, writes unique pages, and delivers a bulk-import-ready CSV — automatically.`,inputUrlCta:`Build my SEO`,inputUrlPlaceholder:`www.yourcompany.com`,inputUrlPrefill:`Go to {url} and build a programmatic SEO page factory. Analyze the site's niche, existing content, and keyword themes. Research 500+ long-tail keyword variations grouped by topic cluster. For each keyword, generate: (1) a unique, SEO-optimized page title, (2) H1 heading, (3) meta description under 160 characters, (4) 300-500 word body copy with natural keyword placement, (5) a 3-question FAQ section with schema-ready Q&A markup, (6) internal link suggestions to related pages on the site, and (7) JSON-LD structured data. Output everything as a CSV with one row per page, columns for each element, ready to bulk import into a CMS. Include a keyword cluster map showing how pages interlink.`,heroOverlaySteps:[`Analyzing your site's niche, content, and keyword themes`,`Researching 500+ long-tail keywords grouped by topic cluster`,`Writing unique titles, body copy, FAQs, and schema markup for each page`,`CSV with 500+ pages, internal links, and schema — ready to import`],generatingSteps:[`Visiting {url} to analyze your niche, site structure, and content gaps`,`Designing an agent to research long-tail keywords and cluster them by topic`,`Configuring page generation pipeline — titles, copy, FAQs, and structured data`,`Setting up CSV export with internal links and CMS-ready formatting`],featureSectionTitle:`From URL to SEO ready`,featureCardTitles:[`Connects to your SEO stack`,`Pages ready to publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Search Console, Airtable, Notion, Google Sheets — Computer delivers pages in the format your CMS expects, ready for bulk upload.`,`Unique copy. Optimized meta tags. FAQ schema. Internal links. Computer delivers hundreds of pages your team can publish immediately.`],capabilitySectionTitle:`Your content factory, on autopilot`,capabilitySectionSubtitle:`Paste your URL, get back hundreds of SEO-ready pages.`,capabilityCards:[{title:`Keyword Research`,description:`Computer finds 500+ long-tail keywords in your niche — grouped into topic clusters with search volume and competition data.`},{title:`Page Generation`,description:`Computer writes unique titles, H1s, meta descriptions, and body copy for every keyword — no duplicate content, no thin pages.`},{title:`Schema & FAQs`,description:`Computer generates FAQ sections and JSON-LD structured data for every page — boosting rich snippet eligibility in search results.`},{title:`Internal Linking`,description:`Computer maps internal links between related pages — building topic authority and helping search engines understand your site structure.`},{title:`Remember & Learn`,description:`Computer remembers your brand voice, keyword themes, and past pages across sessions — so every batch builds on what came before.`},{title:`Ranking Monitoring`,description:`Computer tracks which pages rank and which need updates — and alerts you when new keyword opportunities appear.`}]});export{t as default};
